51:export type SweepOptions = Tags & {
52:  /**
53:   * Colour or Paint, or `(t) => colour`: the tube is split exactly where the colour changes. Default: the colour of
54:   * the nearest part already built to the tube's start (grey when there is none); `bands` override it where they
55:   * cover the tube.
56:   */
57:  color?: Fill | ((t: number) => Fill);
58:  /** `[[tEnd, color], ...]` ascending, in source t: color bands; each band edge splits the mesh (same bone, no cap). */
59:  bands?: ReadonlyArray<readonly [number, Fill]>;
60:  /**
61:   * Bones for a Path source: a joint (rigid), or the chains and joints the path runs through, as one Chain or a list
62:   * in any order (a body drawn from tail tip to snout: `[tail, hips, spine, neck, head]`). The tube is then one mesh
63:   * skinned like a chain source, whichever way each chain runs along the path. Default: the weights of the path's
64:   * first built input, else the joint nearest the path's start. Chain sources always use their own joints.
65:   */
66:  bone?: JointRef | Chain | ReadonlyArray<JointRef | Chain>;
67:  /** "smooth" (default): one continuous mesh bending across joints. "rigid": one round-capped piece per bone. */
68:  skin?: Skin;
69:  /**
70:   * Range of the source to sweep, in source t. It only crops: every other t (radius and shift functions, `color`,
71:   * `bands`, sector ranges, twist, `Sweep.at`) is source t too, so sweeping [0, 0.4] and [0.4, 1] with the same
72:   * options gives the two halves of the one tube. Radius arrays spread over the swept range.
73:   */
74:  from?: number;
75:  to?: number;
76:  section?: Section;
77:  /** Circle sides (default 8 × `detail`). */
78:  sides?: number;
79:  /**
80:   * This tube's own tessellation multiplier (default: the builder's `detail`): default sides, ring spacing along
81:   * the tube and radius tolerance. 0.5 on a small horn or toe; explicit `sides` still wins.
82:   */
83:  detail?: number;
84:  /** Smooth normals (default: circle smooth, box/ngon faceted). */
85:  smooth?: boolean;
86:  caps?: Cap | { start?: Cap; end?: Cap };
87:  /** Rigid only: instead of round caps at bone cuts, extend each piece past the cut by `overlap` × radius (flat end). */
88:  overlap?: number;
89:  /** Extend straight past the start / end along the end tangent at the end radius, in meters (number = both). */
90:  extend?: number | readonly [number, number];
91:  /**
92:   * Colour sectors around the tube, `[[fromDeg, toDeg, color], ...]` on the dorsal clock of `Sweep.at` (0 = the
93:   * side facing world up, 180 = belly). Uncovered angles keep the piece colour. One mesh per sector per piece;
94:   * sector edges get no walls and neighbours share them exactly. Add `fromT, toT` (source t) to limit a sector to
95:   * that stretch of the tube: `[-60, 60, DARK, 0.2, 1]` darkens the back of all but the tip. Sectors only have to
96:   * avoid overlapping where their stretches meet.
97:   */
98:  sectors?: ReadonlyArray<Sector>;
99:  /** Section centre offset `[x, y]` in the same (binormal, normal) axes as `(t) => [rx, ry]`: a sagging belly. */
100:  shift?: readonly [number, number] | ((t: number) => readonly [number, number]);
101:  /** Path sources: start roll, the section's normal (ry direction) leans toward `up`. */
102:  up?: DirectionInput;
103:  /** Path sources: roll about the tangent after parallel transport, total degrees or `(t) => deg` (chains: on `chain()`). */
104:  twist?: Twist;
105:};
