import * as THREE from "three";
import build from "../../samples/africanElephant";
const root = build();
const box = new THREE.Box3().setFromObject(root, true);
console.log("min", box.min.toArray().map((v) => +v.toFixed(3)), "max", box.max.toArray().map((v) => +v.toFixed(3)));
let parts = 0;
let tris = 0;
root.traverse((o) => {
  const m = o as THREE.Mesh;
  if (m.isMesh) {
    parts++;
    const g = m.geometry;
    tris += (g.index ? g.index.count : g.attributes.position.count) / 3;
  }
});
console.log({ parts, tris });

