88:  // ---- skeleton: spine, neck, head ----------------------------------------------------------------------------------
89:  const pelvis = b.joint("pelvis", { at: [0, 2.15, -1.25], role: "spine" });
90:  const spine = b.chain(
91:    "spine",
92:    catmull([
93:      [0, 2.15, -1.25],
94:      [0, 2.1, -0.3],
95:      [0, 2.15, 0.6],
96:      [0, 2.25, 1.45],
97:    ]),
98:    { parent: pelvis, names: ["spine1", "spine2", "spine3"], role: "spine" },
99:  );
100:  const neck = b.chain(
101:    "neck",
102:    catmull([
103:      [0, 2.25, 1.45],
104:      [0, 2.35, 1.75],
105:      [0, 2.45, 2.0],
106:    ]),
107:    { parent: spine.joints[2], names: ["neck1", "neck2"], role: "neck" },
108:  );
109:  const head = b.joint("head", { parent: neck.joints[1], at: [0, 2.45, 2.0], dir: [0, -0.08, 1], role: "head" });
110:  const jaw = b.joint("jaw", { parent: head, at: [0, 2.0, 2.2], aim: [0, 1.93, 2.72], role: "jaw" });
111:
112:  // ---- barrel body --------------------------------------------------------------------------------------------------
113:  const body = b.loft(
114:    [
115:      { at: [0, 2.3, -1.65], w: 1.0, h: 1.15 },
116:      { at: [0, 2.15, -1.3], w: 1.5, h: 1.65 },
117:      { at: [0, 2.0, -0.6], w: 1.68, h: 1.9 },
118:      { at: [0, 2.05, 0.3], w: 1.68, h: 2.0 },
119:      { at: [0, 2.2, 1.0], w: 1.62, h: 2.15 },
120:      { at: [0, 2.2, 1.55], w: 1.28, h: 1.85 },
